async (state) => {
  const { Send } = require('@langchain/langgraph');
  const lastMessage = state.messages[state.messages.length - 1];
  const problem = lastMessage?.content || 'No problem defined';

  return [
    new Send('technical_expert', { ...state, currentExpert: 'technical' }),
    new Send('business_expert', { ...state, currentExpert: 'business' }),
    new Send('ux_expert', { ...state, currentExpert: 'ux' })
  ];
}

async (state, model) => {
  const lastMessage = state.messages[state.messages.length - 1];
  const result = await model.invoke([{ role: 'user', content: `Provide a technical perspective on: ${lastMessage.content}` }]);
  return {
    proposals: { technical: result.content.toString() },
    messages: [{ role: 'assistant', content: `Technical Expert: ${result.content}` }]
  };
}

