async (state, model) => {
  const proposalsText = Object.entries(state.proposals)
    .map(([expert, proposal]) => `${expert.toUpperCase()}: ${proposal}`)
    .join('\n\n');

  const prompt = `Synthesize these expert proposals into a unified decision:\n\n${proposalsText}`;
  const result = await model.invoke([{ role: 'user', content: prompt }]);

  return {
    consensusReached: true,
    messages: [{ role: 'assistant', content: `Coordinator Synthesis: ${result.content}` }]
  };
}

async (state, model) => {
  const lastMessage = state.messages[state.messages.length - 1];
  const result = await model.invoke([{ role: 'user', content: `Based on the synthesis, make a final decision: ${lastMessage.content}` }]);

  return {
    finalDecision: result.content.toString(),
    messages: [{ role: 'assistant', content: `Final Decision: ${result.content}` }]
  };
}

